"""Revoke only profiles/pools generated by this task, using its local controller."""
import datetime
import json
from pathlib import Path
import socket
import sqlite3
import subprocess


def request(payload):
    with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as client:
        client.settimeout(50)
        client.connect('/run/signal-vpn-control/control.sock')
        client.sendall(json.dumps(payload).encode() + b'\n')
        with client.makefile('rb') as incoming:
            result = json.loads(incoming.readline(131073))
    if result.get('ok') is not True:
        raise RuntimeError('Controller refused test cleanup')
    return result


profiles = request({'op': 'list'})['profiles']
pools = request({'op': 'pool-list'})['pools']
prefixes=('QA-pools-20261027T','QA-protocols-20261027T')
test_profiles = [profile for profile in profiles if profile['name'].startswith(prefixes)]
test_pools = [pool for pool in pools if pool['name'].startswith(prefixes)]
baseline = {profile['id'] for profile in profiles if profile not in test_profiles and profile['active']}
pool_baseline = {pool['id'] for pool in pools if pool not in test_pools and pool['active']}
for pool in test_pools:
    request({'op': 'pool-revoke', 'id': pool['id']})
for profile in test_profiles:
    request({'op': 'revoke', 'id': profile['id']})
after = request({'op': 'list'})['profiles']
after_pools = request({'op': 'pool-list'})['pools']
if {profile['id'] for profile in after if profile['active']} != baseline:
    raise RuntimeError('Unexpected active profiles after cleanup')
if {pool['id'] for pool in after_pools if pool['active']} != pool_baseline:
    raise RuntimeError('Unexpected active pools after cleanup')
stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ')
backup = Path('/root') / ('signal-qa-cleanup-' + stamp)
backup.mkdir(mode=0o700)
database = Path('/var/lib/signal-vpn-control/profiles.sqlite')
with sqlite3.connect(database) as source, sqlite3.connect(backup / 'profiles.sqlite') as destination:
    source.backup(destination)
    source.execute('PRAGMA foreign_keys=ON')
    source.execute('BEGIN IMMEDIATE')
    for pool in test_pools:
        source.execute('DELETE FROM pool_profiles WHERE pool_id=?', (pool['id'],))
        source.execute('DELETE FROM pools WHERE id=? AND revoked_at IS NOT NULL', (pool['id'],))
    for profile in test_profiles:
        # Preserve any other existing pool metadata containing a revoked QA row.
        source.execute('DELETE FROM profiles WHERE id=? AND revoked_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pool_profiles WHERE profile_id=?)',
            (profile['id'], profile['id']))
names = ['signal-vpn-web', 'signal-vpn-control', 'signal-vpn', 'signal-caddy', 'signal-app', 'signal-media', 'x-ui']
states = {name: subprocess.check_output(['systemctl', 'is-active', name], text=True).strip() for name in names}
if any(value != 'active' for value in states.values()):
    raise RuntimeError('A service is not active')
print(json.dumps({'temporaryAccessRevoked': True, 'originalProfilesAndPoolsPreserved': True,
    'removedTestProfiles': len(test_profiles), 'removedTestPools': len(test_pools),
    'activeOriginalProfiles': len(baseline), 'activeOriginalPools': len(pool_baseline),
    'services': states, 'backup': str(backup)}))
